from math import gcd
from typing import Dict, List


def stern_table(limit: int) -> List[int]:
    """Bottom-up tabulation of s(0..limit)."""
    s: List[int] = [0] * (limit + 1)
    if limit >= 1:
        s[1] = 1
    for k in range(1, limit // 2 + 1):
        if 2 * k <= limit:
            s[2 * k] = s[k]
        if 2 * k + 1 <= limit:
            s[2 * k + 1] = s[k] + s[k + 1]
    return s


if __name__ == "__main__":
    s = stern_table(19)
    print("Stern prefix:", ", ".join(map(str, s)))
    print("All coprime:", all(gcd(s[n], s[n + 1]) == 1 for n in range(19)))

from typing import Dict, List


def stern(n: int, memo: Dict[int, int] = None) -> int:
    """Direct recursive evaluation of Stern's sequence with memoization."""
    if memo is None:
        memo = {0: 0, 1: 1}
    if n in memo:
        return memo[n]
    if n % 2 == 0:
        v = stern(n // 2, memo)
    else:
        v = stern(n // 2, memo) + stern(n // 2 + 1, memo)
    memo[n] = v
    return v


def fibonacci(k: int) -> int:
    a, b = 0, 1
    for _ in range(k):
        a, b = b, a + b
    return a


def jacobsthal(n: int) -> int:
    return (4 ** n - 1) // 3


if __name__ == "__main__":
    for n in range(8):
        j = jacobsthal(n)
        print(f"n={n}: s(J)={stern(j)}=F(2n)={fibonacci(2*n)}, "
              f"s(2J+1)={stern(2*j+1)}=F(2n+1)={fibonacci(2*n+1)}")

