def row_sum(k: int) -> int:
    """Sum of Stern's sequence over the dyadic block [2^k, 2^{k+1})."""
    return sum(stern(2 ** k + i) for i in range(2 ** k))


if __name__ == "__main__":
    for k in range(9):
        print(f"k={k}: row_sum={row_sum(k)}, 3^k={3 ** k}, "
              f"match={row_sum(k) == 3 ** k}")

